INSERT INTO `interview_questions` VALUES (1,'Focus on the architectural layers (Controller, Service, Repository), database schema, and why specific libraries or patterns were chosen.','INTERMEDIATE','Resume Project Architecture',1,'In your resume, you highlighted projects utilizing Java and Python. Can you walk through the system architecture of your most significant project, detailing the key design decisions and how you handled data persistence?',1),(2,'Cover visibility (CPU caches vs main memory), race conditions, and lock overhead.','INTERMEDIATE','Core Fundamentals',2,'How does Java handle concurrency and thread-safety? Explain the difference between synchronized blocks, volatile variables, and atomic primitives.',1),(3,'Mention EXPLAIN query plans, B-Tree index structures, avoiding SELECT *, and caching strategies.','INTERMEDIATE','Database & Optimization',3,'When querying large datasets in Mysql, how do you diagnose slow queries, and what indexing strategies or query optimizations do you implement to maintain sub-100ms response times?',1),(4,'Focus on the architectural layers (Controller, Service, Repository), database schema, and why specific libraries or patterns were chosen.','INTERMEDIATE','Resume Project Architecture',1,'In your resume, you highlighted projects utilizing Java and JavaScript. Can you walk through the system architecture of your most significant project, detailing the key design decisions and how you handled data persistence?',2),(5,'Cover visibility (CPU caches vs main memory), race conditions, and lock overhead.','INTERMEDIATE','Core Fundamentals',2,'How does Java handle concurrency and thread-safety? Explain the difference between synchronized blocks, volatile variables, and atomic primitives.',2),(6,'Mention EXPLAIN query plans, B-Tree index structures, avoiding SELECT *, and caching strategies.','INTERMEDIATE','Database & Optimization',3,'When querying large datasets in Mysql, how do you diagnose slow queries, and what indexing strate